implementation.cssText:
/* Dyson-inspired REFERENCE IMPLEMENTATION, prepared 2026-11-17.
 * This is original component CSS, NOT a dump of dyson.co.uk stylesheets.
 * Published reference values are unverified against the current UK page.
 * Scope with class="dyson-inspired" on a wrapper or <body>.
 * No logos, photographs or font binaries are included.
 * Load a licensed font separately, or allow the local fallback stack.
 */

.dyson-inspired {
  --dy-color-black: #000000;
  --dy-color-ink: #333333;
  --dy-color-secondary: #555555;
  --dy-color-muted: #999999;
  --dy-color-outline: #919191;
  --dy-color-divider: #dadada;
  --dy-color-light: #ebebeb;
  --dy-color-white: #ffffff;
  --dy-color-cream: #fff8e6;
  --dy-color-green: #79b928;
  --dy-color-blue: #0066cc;
  --dy-color-cyan: #149ecc;
  --dy-color-brown: #ac5d00;
  --dy-font-sans: "DysonFutura", "Futura", "Avenir Next", Arial, sans-serif;
  --dy-font-weight-light: 300;
  --dy-font-weight-regular: 400;
  --dy-font-weight-medium: 500;
  --dy-font-size-caption: 12px;
  --dy-font-size-small: 14px;
  --dy-font-size-body: 16px;
  --dy-font-size-lead: 18px;
  --dy-font-size-h3: 24px;
  --dy-font-size-h2: 28px;
  --dy-font-size-h1: 36px;
  --dy-line-height-body: 1.5;
  --dy-line-height-heading: 1.2;
  --dy-content-max: 1200px;
  --dy-page-gutter: 24px;
  --dy-section-space: 48px;
  --dy-radius-control: 0px;
  --dy-radius-card: 0px;
  --dy-radius-badge: 2px;
  --dy-radius-media: 8px;
  --dy-border-width: 1px;
  --dy-focus-width: 3px;
  --dy-focus-offset: 3px;
  --dy-shadow-flat: none;
  --dy-motion-fast: 160ms;
  --dy-motion-ease: ease-out;
  --dy-layer-header: 20;
  --dy-layer-overlay: 100;
  --dy-layer-dialog: 110;
  --dy-space-0: 0px;
  --dy-space-4: 4px;
  --dy-space-8: 8px;
  --dy-space-12: 12px;
  --dy-space-16: 16px;
  --dy-space-20: 20px;
  --dy-space-24: 24px;
  --dy-space-28: 28px;
  --dy-space-32: 32px;
  --dy-space-40: 40px;
  --dy-space-44: 44px;
  --dy-space-48: 48px;
  --dy-space-64: 64px;
  --dy-space-80: 80px;
  --dy-space-96: 96px;
}

.dyson-inspired, .dyson-inspired *, .dyson-inspired *::before, .dyson-inspired *::after {
  box-sizing: border-box;
}

.dyson-inspired {
  margin: 0;
  color: var(--dy-color-ink);
  background-color: var(--dy-color-white);
  font-family: var(--dy-font-sans);
  font-size: var(--dy-font-size-body);
  font-weight: 400;
  line-height: var(--dy-line-height-body);
  text-rendering: optimizeLegibility;
}

.dyson-inspired .brand-container {
  width: 100%;
  max-width: var(--dy-content-max);
  margin-inline: auto;
  padding-inline: var(--dy-page-gutter);
}

.dyson-inspired .brand-section {
  padding-block: var(--dy-section-space);
}

.dyson-inspired .brand-section--light {
  background-color: var(--dy-color-light);
}

.dyson-inspired .brand-section--warm {
  background-color: var(--dy-color-cream);
}

.dyson-inspired .brand-section--dark {
  color: var(--dy-color-white);
  background-color: var(--dy-color-black);
}

.dyson-inspired .brand-header {
  background-color: var(--dy-color-black);
  color: var(--dy-color-white);
  position: relative;
  z-index: var(--dy-layer-header);
}

.dyson-inspired .brand-header__inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: var(--dy-space-24);
  min-height: 80px;
  padding-block: var(--dy-space-16);
}

.dyson-inspired .brand-nav {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: var(--dy-space-24);
}

.dyson-inspired .brand-nav a {
  color: inherit;
  text-decoration: none;
  font-size: var(--dy-font-size-small);
  font-weight: 500;
}

.dyson-inspired .brand-nav a:hover {
  text-decoration: underline;
  text-underline-offset: 4px;
}

.dyson-inspired .brand-hero {
  color: var(--dy-color-white);
  background-color: var(--dy-color-black);
  padding-block: var(--dy-space-64);
}

.dyson-inspired .brand-hero__layout {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: var(--dy-space-32);
  align-items: center;
}

.dyson-inspired .brand-hero__copy {
  max-width: 36rem;
}

.dyson-inspired h1, .dyson-inspired h2, .dyson-inspired h3, .dyson-inspired .brand-heading {
  margin: 0 0 var(--dy-space-16);
  font-family: var(--dy-font-sans);
  font-weight: 300;
  line-height: var(--dy-line-height-heading);
  letter-spacing: normal;
}

.dyson-inspired h1, .dyson-inspired .brand-heading--1 {
  font-size: var(--dy-font-size-h1);
}

.dyson-inspired h2, .dyson-inspired .brand-heading--2 {
  font-size: var(--dy-font-size-h2);
}

.dyson-inspired h3, .dyson-inspired .brand-heading--3 {
  font-size: var(--dy-font-size-h3);
}

.dyson-inspired p {
  margin: 0 0 var(--dy-space-16);
}

.dyson-inspired .brand-lead {
  font-size: var(--dy-font-size-lead);
  line-height: 1.5;
}

.dyson-inspired .brand-small {
  font-size: var(--dy-font-size-small);
}

.dyson-inspired .brand-legal {
  color: var(--dy-color-secondary);
  font-size: var(--dy-font-size-caption);
  line-height: 1.6;
}

.dyson-inspired .brand-link {
  color: var(--dy-color-blue);
  text-decoration: underline;
  text-underline-offset: 3px;
}

.dyson-inspired .brand-link:hover {
  text-decoration-thickness: 2px;
}

.dyson-inspired .brand-section--dark .brand-link, .dyson-inspired .brand-hero .brand-link, .dyson-inspired .brand-footer .brand-link {
  color: var(--dy-color-white);
}

.dyson-inspired .brand-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--dy-space-8);
  min-height: 48px;
  padding: 16px 24px;
  border: 1px solid transparent;
  border-radius: var(--dy-radius-control);
  font-family: inherit;
  font-size: var(--dy-font-size-body);
  font-weight: 500;
  line-height: 1.25;
  text-align: center;
  text-decoration: none;
  cursor: pointer;
  transition: background-color var(--dy-motion-fast) var(--dy-motion-ease), color var(--dy-motion-fast) var(--dy-motion-ease), border-color var(--dy-motion-fast) var(--dy-motion-ease);
}

.dyson-inspired .brand-button--primary {
  background-color: var(--dy-color-ink);
  color: var(--dy-color-white);
  border-color: var(--dy-color-ink);
}

.dyson-inspired .brand-button--primary:hover {
  background-color: var(--dy-color-black);
  border-color: var(--dy-color-black);
}

.dyson-inspired .brand-button--purchase {
  background-color: var(--dy-color-green);
  color: var(--dy-color-black);
  border-color: var(--dy-color-green);
}

.dyson-inspired .brand-button--purchase:hover {
  box-shadow: inset 0 0 0 2px var(--dy-color-black);
}

.dyson-inspired .brand-button--secondary {
  color: var(--dy-color-ink);
  background-color: transparent;
  border-color: var(--dy-color-ink);
}

.dyson-inspired .brand-button--secondary:hover {
  background-color: var(--dy-color-light);
}

.dyson-inspired .brand-button--inverse {
  color: var(--dy-color-black);
  background-color: var(--dy-color-white);
  border-color: var(--dy-color-white);
}

.dyson-inspired .brand-button--inverse:hover {
  background-color: var(--dy-color-light);
  border-color: var(--dy-color-light);
}

.dyson-inspired .brand-button--text {
  color: inherit;
  background-color: transparent;
  border-color: transparent;
  padding-inline: 0;
  text-decoration: underline;
  text-underline-offset: 4px;
}

.dyson-inspired .brand-button:disabled, .dyson-inspired .brand-button[aria-disabled="true"] {
  color: var(--dy-color-secondary);
  background-color: var(--dy-color-light);
  border-color: var(--dy-color-divider);
  box-shadow: none;
  cursor: not-allowed;
}

.dyson-inspired .brand-button-group {
  display: flex;
  flex-wrap: wrap;
  gap: var(--dy-space-16);
  align-items: center;
}

.dyson-inspired :where(a, button, input, select, textarea, summary, [tabindex]):focus-visible {
  outline: var(--dy-focus-width) solid var(--dy-color-blue);
  outline-offset: var(--dy-focus-offset);
}

.dyson-inspired .brand-header :focus-visible, .dyson-inspired .brand-footer :focus-visible, .dyson-inspired .brand-hero :focus-visible, .dyson-inspired .brand-section--dark :focus-visible {
  outline-color: var(--dy-color-white);
}

.dyson-inspired .brand-card {
  color: var(--dy-color-ink);
  background-color: var(--dy-color-white);
  border: var(--dy-border-width) solid var(--dy-color-light);
  border-radius: var(--dy-radius-card);
  padding: var(--dy-space-24);
  box-shadow: var(--dy-shadow-flat);
  display: flex;
  flex-direction: column;
  gap: var(--dy-space-16);
  min-width: 0;
}

.dyson-inspired .brand-card__media {
  display: block;
  width: 100%;
  height: auto;
  aspect-ratio: 1 / 1;
  object-fit: contain;
}

.dyson-inspired .brand-card__actions {
  margin-top: auto;
}

.dyson-inspired .brand-product-grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: var(--dy-space-24);
}

.dyson-inspired .brand-price {
  font-size: var(--dy-font-size-h3);
  font-weight: 400;
  line-height: 1.3;
  color: var(--dy-color-ink);
}

.dyson-inspired .brand-price--old {
  font-size: var(--dy-font-size-small);
  text-decoration: line-through;
  color: var(--dy-color-secondary);
}

.dyson-inspired .brand-badge {
  display: inline-flex;
  align-self: flex-start;
  padding: 4px 8px;
  border-radius: var(--dy-radius-badge);
  background-color: var(--dy-color-brown);
  color: var(--dy-color-white);
  font-size: var(--dy-font-size-caption);
  font-weight: 500;
  line-height: 1.4;
}

.dyson-inspired .brand-field {
  display: grid;
  gap: var(--dy-space-8);
}

.dyson-inspired .brand-label {
  font-size: var(--dy-font-size-small);
  font-weight: 500;
}

.dyson-inspired .brand-input, .dyson-inspired .brand-select, .dyson-inspired .brand-textarea {
  width: 100%;
  min-height: 48px;
  padding: 12px 16px;
  font-family: inherit;
  font-size: var(--dy-font-size-body);
  line-height: 1.5;
  color: var(--dy-color-ink);
  background-color: var(--dy-color-white);
  border: 1px solid var(--dy-color-outline);
  border-radius: var(--dy-radius-control);
}

.dyson-inspired .brand-input::placeholder, .dyson-inspired .brand-textarea::placeholder {
  color: var(--dy-color-secondary);
  opacity: 1;
}

.dyson-inspired .brand-input:disabled, .dyson-inspired .brand-select:disabled, .dyson-inspired .brand-textarea:disabled {
  background-color: var(--dy-color-light);
  cursor: not-allowed;
}

.dyson-inspired .brand-textarea {
  min-height: 144px;
  resize: vertical;
}

.dyson-inspired .brand-help {
  color: var(--dy-color-secondary);
  font-size: var(--dy-font-size-caption);
}

.dyson-inspired .brand-divider {
  border: 0;
  border-top: 1px solid var(--dy-color-divider);
  margin-block: var(--dy-space-32);
}

.dyson-inspired .brand-accordion {
  border-block-start: 1px solid var(--dy-color-divider);
}

.dyson-inspired .brand-accordion > summary {
  cursor: pointer;
  padding-block: var(--dy-space-20);
  font-size: var(--dy-font-size-lead);
  font-weight: 400;
}

.dyson-inspired .brand-accordion__content {
  padding-bottom: var(--dy-space-24);
}

.dyson-inspired .brand-footer {
  background-color: var(--dy-color-black);
  color: var(--dy-color-white);
  padding-block: var(--dy-space-48);
}

.dyson-inspired .brand-footer__grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: var(--dy-space-32);
}

.dyson-inspired .brand-footer a {
  color: inherit;
}

.dyson-inspired .brand-footer .brand-legal {
  color: var(--dy-color-white);
}

@media (min-width: 640px) {
  .dyson-inspired .brand-product-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .dyson-inspired .brand-footer__grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (min-width: 1024px) {
  .dyson-inspired .brand-hero__layout {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .dyson-inspired .brand-product-grid {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

  .dyson-inspired .brand-footer__grid {
    grid-template-columns: repeat(4, minmax(0, 1fr));
  }
}

@media (max-width: 639px) {
  .dyson-inspired {
    --dy-page-gutter: 16px;
    --dy-section-space: 32px;
    --dy-font-size-h1: 32px;
    --dy-font-size-h2: 24px;
  }

  .dyson-inspired .brand-hero {
    padding-block: 40px;
  }

  .dyson-inspired .brand-button-group {
    align-items: stretch;
    flex-direction: column;
  }

  .dyson-inspired .brand-header__inner {
    min-height: 64px;
  }
}

@media (prefers-reduced-motion: reduce) {
  .dyson-inspired .brand-button {
    transition: none;
  }
}
